// Native adaptation of the final Follow beat in https://hyperframes.heygen.com/catalog/blocks/blue-sweater-intro-video.
// Copyright 2026 HeyGen, Inc. Apache-2.0; original source credited Joe Sai.
// Changes: standalone native beat, fictional editable profile, generated portrait; no source images/audio.
export default defineSpanScene({
  id: "creator-follow-card", width: 1920, height: 1080, durationMs: 4500, editPreviewMs: 2400,
  variables: {
    width: numberVar(1920), height: numberVar(1080), creator: stringVar("Elias Reed"), handle: stringVar("@eliasframes"),
    heroSrc: stringVar("data:image/png;base64,"),
    avatarSrc: stringVar("data:image/png;base64,"), bio: stringVar("Short films, quiet details. Making each frame count in Mont."),
    actionLabel: stringVar("Follow"), confirmedLabel: stringVar("Following"),
    background: colorVar("#F7F1EF"), surface: colorVar("#FBFAF6"), foreground: colorVar("#11110F"), muted: colorVar("#807D76"),
    button: colorVar("#11110F"), confirmedButton: colorVar("#2F2F2F"),
    entryAtMs: numberVar(100), pressAtMs: numberVar(1120), cursorVisible: numberVar(1),
    cursorSrc: stringVar("data:image/png;base64,"),
  },
  computeds: {
    scale: computed.number(() => Math.min(vars.width / 1920, vars.height / 1080)),
    clock: computed.number(() => time.loop(4500) * 4500),
    entry: computed.number(() => Math.max(0, Math.min(1, (computed.clock - vars.entryAtMs) / 600))),
    enterEase: computed.number(() => computed.entry >= 1 ? 1 : 1 - Math.pow(2, -10 * computed.entry)),
    press: computed.number(() => Math.max(0, Math.min(1, (computed.clock - vars.pressAtMs) / 80))),
    release: computed.number(() => Math.max(0, Math.min(1, (computed.clock - vars.pressAtMs - 80) / 160))),
    buttonScale: computed.number(() => computed.clock < vars.pressAtMs + 80 ? 1 - 0.05 * Math.pow(computed.press, 3) : 0.95 + 0.05 * (1 - Math.pow(1 - computed.release, 3))),
    oldLabel: computed.number(() => 1 - Math.max(0, Math.min(1, (computed.clock - vars.pressAtMs - 80) / 80))),
    newLabel: computed.number(() => Math.max(0, Math.min(1, (computed.clock - vars.pressAtMs - 80) / 160))),
    colorSwap: computed.number(() => Math.max(0, Math.min(1, (computed.clock - vars.pressAtMs - 80) / 120))),
    particle: computed.number(() => Math.max(0, Math.min(1, (computed.clock - vars.pressAtMs - 80) / 480))),
    particleEase: computed.number(() => 1 - Math.pow(1 - computed.particle, 3)),
    ring: computed.number(() => Math.max(0, Math.min(1, (computed.clock - vars.pressAtMs - 80) / 280))),
    cursorTravel: computed.number(() => Math.max(0, Math.min(1, (computed.clock - vars.entryAtMs - 100) / Math.max(1, vars.pressAtMs - vars.entryAtMs - 200)))),
    // Quintic easing brings velocity and acceleration to zero at both ends.
    cursorEase: computed.number(() => computed.cursorTravel * computed.cursorTravel * computed.cursorTravel * (10 + computed.cursorTravel * (-15 + 6 * computed.cursorTravel))),
    cursorSettle: computed.number(() => Math.max(0, Math.min(1, (computed.clock - vars.pressAtMs - 240) / 460))),
    cursorSettleEase: computed.number(() => computed.cursorSettle * computed.cursorSettle * computed.cursorSettle * (10 + computed.cursorSettle * (-15 + 6 * computed.cursorSettle))),
    // Residual motion fades in during settling; independent slow arcs avoid a rigid shared bob.
    cardDriftTime: computed.number(() => Math.max(0, (computed.clock - vars.entryAtMs - 450) / 1000)),
    cardDriftBlend: computed.number(() => 1 - Math.pow(2, -4 * computed.cardDriftTime * computed.cardDriftTime)),
    cardDriftX: computed.number(() => 5 * Math.sin(0.65 * computed.cardDriftTime) * computed.cardDriftBlend),
    cardDriftY: computed.number(() => -4 * Math.sin(0.85 * computed.cardDriftTime) * computed.cardDriftBlend),
    cursorDriftTime: computed.number(() => Math.max(0, (computed.clock - vars.pressAtMs - 300) / 1000)),
    cursorDriftBlend: computed.number(() => 1 - Math.pow(2, -4 * computed.cursorDriftTime * computed.cursorDriftTime)),
    cursorDriftX: computed.number(() => 6 * Math.sin(1.2 * computed.cursorDriftTime) * computed.cursorDriftBlend),
    cursorDriftY: computed.number(() => 4.5 * Math.sin(0.8 * computed.cursorDriftTime) * computed.cursorDriftBlend),
    // Cubic Bézier: (378,424) → (650,300) → (1110,330) → Follow (1255,442).
    cursorX: computed.number(() => 378 * Math.pow(1 - computed.cursorEase, 3) + 3 * 650 * Math.pow(1 - computed.cursorEase, 2) * computed.cursorEase + 3 * 1110 * (1 - computed.cursorEase) * computed.cursorEase * computed.cursorEase + 1255 * Math.pow(computed.cursorEase, 3) + 66 * computed.cursorSettleEase - 22 * computed.cursorSettleEase * computed.cursorSettleEase),
    cursorY: computed.number(() => 424 * Math.pow(1 - computed.cursorEase, 3) + 3 * 300 * Math.pow(1 - computed.cursorEase, 2) * computed.cursorEase + 3 * 330 * (1 - computed.cursorEase) * computed.cursorEase * computed.cursorEase + 442 * Math.pow(computed.cursorEase, 3) + 6 * computed.cursorSettleEase + 30 * computed.cursorSettleEase * computed.cursorSettleEase),
  },
  render({vars, computed}) {
    return <Scene width={vars.width} height={vars.height}>
      <Rect id="background" width={vars.width} height={vars.height} fill={vars.background} />
      {/* Canonical CLI preloads only opacity-1 images at t=0; retain off-canvas resource bindings. */}
      <Image borderWidth={0} borderColor="transparent" id="avatar-prewarm" src={vars.avatarSrc} x={-4096} y={-4096} width={1} height={1} />
      <Image borderWidth={0} borderColor="transparent" id="hero-prewarm" src={vars.heroSrc} x={-4096} y={-4096} width={1} height={1} />
      <Group id="frame" x={(vars.width - 1920 * computed.scale) / 2} y={(vars.height - 1080 * computed.scale) / 2} width={0} height={0} pivotX={0} pivotY={0} scaleX={computed.scale} scaleY={computed.scale}>
        <Group id="creator-card" x={960 + computed.cardDriftX} y={393 + 34 * (1 - computed.enterEase) + computed.cardDriftY} width={0} height={0} pivotX={0} pivotY={0} scaleX={0.88 + 0.12 * computed.enterEase} scaleY={0.88 + 0.12 * computed.enterEase} opacity={computed.enterEase} blur={12 * (1 - computed.enterEase)}>
          <Rect id="card-edge" x={-400} y={-215} width={800} height={430} radius={36} fill="#DCD8CF" shadowColor="#241F18" shadowBlur={35} shadowOffsetY={28} shadowOpacity={0.065} />
          <Rect id="card-surface" x={-399} y={-214} width={798} height={428} radius={35} fill={vars.surface} />
          <Image id="banner" src={vars.heroSrc} x={-399} y={-214} width={798} height={150} borderWidth={0} borderColor="transparent" />
          <Rect id="platform-chip" x={327} y={-190} width={44} height={44} radius={14} fill={vars.foreground} />
          <Text id="platform-name" text="x" x={327} y={-185} width={44} height={34} fontFamily="Inter" fontWeight={700} size={28} lineHeight={1.2} fit="none" color={vars.surface} align="center" />
          <Rect id="avatar-ring" x={-347} y={-120} width={118} height={118} radius={59} fill={vars.surface} shadowColor="#1486B8" shadowBlur={17} shadowOffsetY={18} shadowOpacity={0.1} />
          <Image borderWidth={0} borderColor="transparent" id="creator-avatar" src={vars.avatarSrc} x={-342} y={-115} width={108} height={108} />
          <Text id="creator-name" text={vars.creator} x={-347} y={22} width={480} height={44} fontFamily="Inter" fontWeight={600} size={44} letterSpacing={-2.42} lineHeight={1} fit="none" color={vars.foreground} />
          <Text id="creator-handle" text={vars.handle} x={-347} y={74} width={650} height={26} fontFamily="Inter" fontWeight={400} size={26} letterSpacing={-0.65} lineHeight={1} fit="none" color={vars.muted} />
          <Text id="creator-bio" text={vars.bio} x={-347} y={120} width={694} height={58} fontFamily="Inter" fontWeight={400} size={25} letterSpacing={-0.875} lineHeight={1.16} fit="none" color={vars.foreground} />
          <Group id="follow-button" x={266} y={49} width={0} height={0} pivotX={0} pivotY={0} scaleX={computed.buttonScale} scaleY={computed.buttonScale}>
          <Rect id="activation-ring" x={-87 * (1 + 0.4 * computed.ring)} y={-27 * (1 + 0.7 * computed.ring)} width={174 * (1 + 0.4 * computed.ring)} height={54 * (1 + 0.7 * computed.ring)} radius={27 * (1 + 0.7 * computed.ring)} fill="transparent" stroke="#1683A3" strokeWidth={2} opacity={computed.clock >= vars.pressAtMs + 80 ? 0.6 * (1 - computed.ring) : 0} />
          <Repeat items={[0.12, 0.81, 1.57, 2.42, 3.08, 3.94, 4.71, 5.52, 6.0]} render={(angle,index) => (
            <Ellipse id={"activation-particle-" + index} x={Math.cos(angle) * (87 + 42 + (index % 3) * 11) * computed.particleEase - 3} y={Math.sin(angle) * (27 + 38 + (index % 4) * 8) * computed.particleEase - 3} width={4 + index % 3} height={4 + index % 3} fill="#1683A3" opacity={computed.clock >= vars.pressAtMs + 80 && computed.particle < 1 ? 1 - computed.particle * computed.particle : 0} />
          )} />
            <Rect id="button-surface" x={-87} y={-27} width={174} height={54} radius={18} fill={computed.clock < vars.pressAtMs + 80 ? vars.button : vars.confirmedButton} />
            <Text id="action-label" text={vars.actionLabel} x={-87} y={-14.4} width={174} height={28.8} fontFamily="Inter" fontWeight={600} size={24} letterSpacing={-0.84} lineHeight={1.2} fit="none" color={vars.surface} align="center" opacity={computed.oldLabel} />
            <Group id="confirmed-state" width={0} height={0} pivotX={0} pivotY={0} opacity={computed.newLabel}>
              <Text id="confirmed-label" text={vars.confirmedLabel} x={-63} y={-14.4} width={100} height={28.8} fontFamily="Inter" fontWeight={600} size={24} letterSpacing={-0.84} lineHeight={1.2} fit="none" color={vars.surface} align="center" />
            <Path id="confirmed-check" x={45} y={-10} width={20} height={20} viewBox="0 0 24 24" d="M4 12 L10 18 L21 5" fill="none" stroke={vars.surface} strokeWidth={3} strokeLineCap="round" strokeLineJoin="round" />
            </Group>
          </Group>
        </Group>
        <Group id="cursor-motion" x={computed.cursorX + computed.cursorDriftX} y={computed.cursorY + computed.cursorDriftY} width={0} height={0} pivotX={0} pivotY={0} rotation={-5} opacity={vars.cursorVisible}>
          <Image id="pointer" src={vars.cursorSrc} x={-13.3333333333} y={-10} width={80} height={80} borderWidth={0} borderColor="transparent" />
        </Group>
      </Group>
    </Scene>;
  },
});
